'use strict';

// MODULES //

var bench = require( '@stdlib/bench-harness' );
var Complex128 = require( '@stdlib/complex-float64' );
var randu = require( '@stdlib/random-base-randu' );
var isArrayLike = require( '@stdlib/assert-is-array-like' );
var pkg = require( './../package.json' ).name;
var reim = require( './../lib' );


// MAIN //

bench( pkg, function benchmark( b ) {
	var arr;
	var z;
	var i;

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		z = new Complex128( randu(), randu() );
		arr = reim( z );
		if ( arr.length === 0 ) {
			b.fail( 'should not be empty' );
		}
	}
	b.toc();
	if ( !isArrayLike( arr ) ) {
		b.fail( 'should return an array' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});","lineStart":1,"lineEnd":52,"totalLines":52,"truncated":false}},"title":"repos/pc-lib-3456/complex-reim/benchmark/benchmark.js","time":{"start":1783258029890,"end":1783258029894}},"id":"prt_f32761db0001Tl8Fefco9yPD6B","sessionID":"ses_0cd8ac3eaffegm4wlSN8a0Cpnv","messageID":"msg_f327611970013gSSAuBU8CEWWe"}}

